(function(){function openAncestors(target){for(let node=target?.parentElement;node;node=node.parentElement)if(node.tagName==='DETAILS')node.open=true;}function openHash(){const raw=location.hash.slice(1);if(!raw||raw.startsWith('v2-node='))return;try{openAncestors(document.getElementById(decodeURIComponent(raw)));}catch{}}document.addEventListener('click',event=>{const link=event.target.closest('a[href^="#"]');if(!link)return;const raw=link.getAttribute('href').slice(1);if(raw&&!raw.startsWith('v2-node='))try{openAncestors(document.getElementById(decodeURIComponent(raw)));}catch{}});addEventListener('hashchange',openHash);if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',openHash);else openHash();})();